"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

// OTP Input: generated by UIX from the design system. Same variants and sizes as the Figma component.

const otpInputVariants = cva(
  "skin-quiet flex flex-col rounded-[inherit] gap-2",
  {
    variants: {
      length: {
        "4": "",
        "6": "",
      },
    },
    defaultVariants: {
      length: "6",
    },
  },
);

export interface OtpInputProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue">,
    VariantProps<typeof otpInputVariants> {
  /** The code typed so far (controlled). */
  value?: string;
  defaultValue?: string;
  /** Called on every change with the digits so far. */
  onValueChange?: (value: string) => void;
  /** Called once every box is filled. */
  onComplete?: (value: string) => void;
  /** Error message; also marks the boxes invalid. */
  error?: string;
  /** Text under the boxes. */
  helper?: React.ReactNode;
  /** Name of a hidden input that carries the code in a form. */
  name?: string;
  disabled?: boolean;
}

const OtpInput = React.forwardRef<HTMLDivElement, OtpInputProps>(
  ({ className, length, value, defaultValue = "", onValueChange, onComplete, error, helper, name, disabled = false, ...props }, ref) => {
    const count = Number(length ?? "6");
    const [inner, setInner] = React.useState(defaultValue);
    const current = (value ?? inner).slice(0, count);
    const boxes = React.useRef<(HTMLInputElement | null)[]>([]);
    const hintId = React.useId();
    const message = error || helper;
    const update = (next: string) => {
      const digits = next.split("").filter((char) => char >= "0" && char <= "9").join("").slice(0, count);
      setInner(digits);
      onValueChange?.(digits);
      if (digits.length === count) onComplete?.(digits);
      return digits;
    };
    return (
      <div data-slot="otp-input" data-kind="field" ref={ref} className={cn(otpInputVariants({ length }), className)} {...props}>
        <div role="group" aria-label="One-time code" className="flex items-center rounded-[inherit] gap-2" onPaste={(event) => {
          event.preventDefault();
          const digits = update(event.clipboardData.getData("text"));
          boxes.current[Math.min(digits.length, count - 1)]?.focus();
        }}>
          {Array.from({ length: count }, (_, index) => (
            <React.Fragment key={index}>
              {count === 6 && index === 3 ? <span aria-hidden className="h-0.5 w-3 bg-line-strong" /> : null}
              <input
                ref={(node) => {
                  boxes.current[index] = node;
                }}
                data-kind="field"
                inputMode="numeric"
                autoComplete={index === 0 ? "one-time-code" : "off"}
                maxLength={1}
                disabled={disabled}
                aria-label={"Digit " + (index + 1) + " of " + count}
                aria-invalid={!!error}
                aria-describedby={message ? hintId : void 0}
                value={current[index] ?? ""}
                onChange={(event) => {
                  const digit = event.target.value.slice(-1);
                  const slot = Math.min(index, current.length);
                  update(current.slice(0, slot) + digit + current.slice(slot + 1));
                  if (digit) boxes.current[slot + 1]?.focus();
                }}
                onKeyDown={(event) => {
                  if (event.key === "Backspace" && !current[index]) boxes.current[index - 1]?.focus();
                }}
                onFocus={(event) => event.target.select()}
                className={cn("text-center rounded-[inherit] h-[56px] w-12 text-heading-4 text-fg-primary placeholder:text-fg-tertiary border border-line-default bg-surface hover:border-line-strong focus-visible:ring-3 focus-visible:ring-line-focus focus-visible:border-line-focus disabled:cursor-not-allowed disabled:bg-disabled", error && "border-line-danger hover:border-line-danger focus-visible:border-line-danger focus-visible:ring-line-danger")}
              />
            </React.Fragment>
          ))}
        </div>
        {name ? <input type="hidden" name={name} value={current} /> : null}
        {message ? <p id={hintId} className={cn("text-body-small text-fg-secondary", error && "text-fg-danger")}>{message}</p> : null}
      </div>
    );
  },
);
OtpInput.displayName = "OtpInput";

export { OtpInput, otpInputVariants };
